    // inlining of macro Vec_PtrForEachEntry
    for  i = 0; (i < Vec_PtrSize(p.vForest)) && (((pNode) = (Rwt_Node_t *)Vec_PtrEntry(p.vForest, i)), 1); i++  {
        pNode.TravId = 0;
    }
    p.nTravIds = 1;
}

